  description: "It opens as a draft. Nothing runs until you press Send.",
};

function summarize(
  appPath: string,
): { ok: true; value: LinkSummary } | { ok: false; error: string } {
  const url = new URL(appPath, window.location.origin);
  if (url.pathname !== "/new") {
